<?php $cardVariants=has_variants($p)&&variants_ready(); ?>
<article class="product-card"><a class="product-picture" href="/product/<?= e($p['slug']) ?>"><img src="<?= e(image_url(product_images($p)[0]??'/assets/favicon.svg')) ?>" alt="<?= e($p['name']) ?>" loading="lazy" width="600" height="750"><?php if((int)$p['stock']<=0): ?><span class="badge sold-out-badge">Sold out</span><?php elseif(!$cardVariants&&product_price($p)<(int)$p['price']): ?><span class="badge">A lovely little offer</span><?php endif ?></a><div class="product-caption"><div><span class="eyebrow"><?= e($p['category_name']??'Accessories') ?></span><h3><a href="/product/<?= e($p['slug']) ?>"><?= e($p['name']) ?></a></h3><span><?= $cardVariants?'From ':'' ?><?= money(product_price($p)) ?></span><?php if(!$cardVariants&&product_price($p)<(int)$p['price']): ?><del><?= money((int)$p['price']) ?></del><?php endif ?><?php if(offer_product_conditions($p)): ?><small class="offer-terms">Basket offers available</small><?php endif ?></div><?php if($cardVariants):$opts=variant_options($p['id']);$colors=count(array_filter($opts,fn($o)=>$o['kind']==='color'&&$o['active']));$sizes=count(array_filter($opts,fn($o)=>$o['kind']==='size'&&$o['active'])); ?><small class="variant-indicator"><?= $colors?$colors.' colors':'' ?><?= $colors&&$sizes?' · ':'' ?><?= $sizes?$sizes.' sizes':'' ?></small><a class="add-round" href="/product/<?= e($p['slug']) ?>" aria-label="Choose options for <?= e($p['name']) ?>">Choose</a><?php else: ?><button class="add-round" data-add="<?= e($p['id']) ?>" aria-label="Add <?= e($p['name']) ?> to your bag" <?= !$p['stock']?'disabled':'' ?>>+</button><?php endif ?></div></article>
